const cpf = ($input.first().json.cpf || '').replace(/\D/g, '');
let dt = $input.first().json.dt_nascimento || '';
let dt_nascimento = '';

if (dt.includes('/')) {
  const [d, m, y] = dt.split('/');
  dt_nascimento = `${y.padStart(4,'19')}-${m.padStart(2,'0')}-${d.padStart(2,'0')}`;
} else if (dt.includes('-')) {
  dt_nascimento = dt;
} else {
  dt_nascimento = dt;
}

return [{ json: { cpf, dt_nascimento } }];

