DECLARE
  v_nr_interno_conta NUMBER;
  v_nr_atendimento   NUMBER := {{ $("Oracle - Get nr_atendimento").first().json["NR_ATENDIMENTO"] }};
BEGIN
  -- 1. Busca a conta vinculada ao atendimento
  SELECT MAX(nr_interno_conta)
  INTO v_nr_interno_conta
  FROM conta_paciente
  WHERE nr_atendimento = v_nr_atendimento;

  -- 2. SÃƒÂ³ executa se a conta existir (evita erro de parÃƒÂ¢metro vazio)
  IF (v_nr_interno_conta IS NOT NULL) THEN
    GERAR_LANCAMENTO_AUTOMATICO(
      NM_USUARIO_P        => 'tasy',
      NR_INTERNO_CONTA_P  => TO_CHAR(v_nr_interno_conta),
      NR_ATENDIMENTO_P    => TO_CHAR(v_nr_atendimento),
      DS_ADICIONAL_1_P    => NULL,
      DS_ADICIONAL_2_P    => NULL,
      DS_ADICIONAL_3_P    => NULL,
      NR_SEQ_EVENTO_P     => 26,
      NR_SEQUENCIA_P      => NULL,
      DS_ADICIONAL_4_P    => NULL,
      CD_LOCAL_ESTOQUE_P  => NULL
    );
    COMMIT;
  END IF;
END;

